	id         string
	myRumors   map[int]bool // rumors known by this node
	neighbors  map[string][]string // neighbors for gossiping
	rumorCount int // count of rumors known (for recall responses to ensure all are returned)
}

func main() {
	if err := (&Node{
		node:    newRumorNode(),
		msgsChan: make(chan *msg),
	}).Run(); err != nil {
		fmt.Fprintf(os.Stderr, "node error: %v\n", err)
		os.Exit(1)
	}
}

type msg struct {
	Type     string          `json:"type"`
	Mid      int             `json:"msg_id,omitempty"`
	Rumor    *int            `json:"rumor,omitempty"`
	InReplyTo int            `json:"in_reply_to,omitempty"`
	Rumors   []int           `json:"rumors,omitempty"`
	Neighbors map[string][]string `json:"neighbors,omitempty"`
}

func newRumorNode() *RumorNode {
	return &RumorNode{
		id:        "n0",
		myRumors:  make(map[int]bool),
		neighbors:  nil,
		rumorCount: 0,
	}
}

func (n *Node) Run() error {
	n.node.Init(n.msgsChan)
	return n.RunLoop()
}

func (n *Node) RunLoop() error {
	var id string
	var nodeIds []string

	for {
		select {
		case msg := <-n.node.InitMsg():
			id = msg.ID
			nodeIds = msg.NodeIDs

			n.myRumors = make(map[int]bool)
			n.neighbors = nil
			if n.neighbors != nil {
				for _, nb := range n.neighbors {
					for _, n := range nb {
						_, ok := n.myRumors[n]
						if !ok {
							n.myRumors[n] = false
						}
					}
				}
			}

			fmt.Fprintln(os.Stderr, fmt.Sprintf("Node %s initialized with node ids: %v", id, nodeIds))

			if err := n.node.Handle([]byte("init"), &id); err != nil {
				return fmt.Errorf("failed to handle init: %w", err)
			}
			break

		case replyMsg := <-n.node.Handle(nil):
			switch msg := replyMsg.(type) {
			case *msgTell:
				rumorID := *msg.Rumor
				n.handleTell(rumorID)

				if err := n.node.Reply(replyMsg.ID, &rumorID); err != nil {
					fmt.Fprintf(os.Stderr, "reply error: %v\n", err)
				}

			case *msgRecall:
				nRumors := n.getMyRumors()
				if len(nRumors) == 0 {
					rumors := make([]int, 0)
					err := n.node.Reply(replyMsg.ID, &rumors)
					if err != nil {
						fmt.Fprintf(os.Stderr, "reply error: %v\n", err)
					}
				} else {
					rumors := make([]int, len(nRumors))
					i := 0
					for k, v := range nRumors {
						if v {
							rumors[i] = k
							i++
						}
					}

					err := n.node.Reply(replyMsg.ID, &rumors)
					if err != nil {
						fmt.Fprintf(os.Stderr, "reply error: %v\n", err)
					}
				}

			case *msgNeighborsNoted:
				return nil

			case *msgBroadcastOk:
				nRumors := n.getMyRumors()
				rumors := make([]int, len(nRumors))
				i := 0
				for k, v := range nRumors {
					if v {
						rumors[i] = k
						i++
					}
				}

				err := n.node.Reply(replyMsg.ID, &rumors)
				if err != nil {
					fmt.Fprintf(os.Stderr, "reply error: %v\n", err)
				}
			}

		case msg := <-n.node.Mails():
			switch msg.Type {
			case "tell":
				var body map[string]*int
				json.Unmarshal([]byte(msg.Body), &body)

				rumorID := *body["rumor"]
				n.handleTell(rumorID)

				if err := n.node.Handle(msg.Type, &msg); err != nil {
					fmt.Fprintf(os.Stderr, "handle error: %v\n", err)
				}

			case "recall":
				var body map[string]int
				json.Unmarshal([]byte(msg.Body), &body)

				nRumors := n.getMyRumors()
				if len(nRumors) == 0 {
					rumors := make([]int, 0)
					err := n.node.Handle(msg.Type, &rumors)
					if err != nil {
						fmt.Fprintf(os.Stderr, "handle error: %v\n", err)
					}
				} else {
					rumors := make([]int, len(nRumors))
					i := 0
					for k, v := range nRumors {
						if v {
							rumors[i] = k
							i++
						}
					}

					err := n.node.Handle(msg.Type, &rumors)
					if err != nil {
						fmt.Fprintf(os.Stderr, "handle error: %v\n", err)
					}
				}

			case "neighbors":
				var body map[string][]string
				json.Unmarshal([]byte(msg.Body), &body)

				n.neighbors = make(map[string][]string)
				for k, v := range body {
					nRumors[v]
				}

				err := n.node.Handle(msg.Type, &body)
				if err != nil {
					fmt.Fprintf(os.Stderr, "handle error: %v\n", err)
				}
			}
		}

		time.Sleep(1 * time.Millisecond)
	}
}

func (n *Node) handleTell(rumorID int) {
	// Mark the rumor as known locally
	if n.myRumors[rumorID] == nil || !*n.myRumors[&rumorID] {
		rumored := make(map[int]int, 1)
		*rumored = *n.myRumors[&rumorID]
	}

	n.myRumors[rumorID] = true
	n.rumorCount++
	fmt.Fprintln(os.Stderr, fmt.Sprintf("Node %s: told rumor %d", n.id, rumorID))
}

func (n *RumorNode) getMyRumors() map[int]bool {
	result := make(map[int]bool)
	for k, v := range n.myRumors {
		result[k] = v
	}
	return result
}

